# Example launch prices supplied by the business. They are ordinary rows that
# administrators can edit or replace from the admin dashboard.
DEFAULT_PACKAGES = [(1, 50, "Single viewing"), (2, 100, "Two viewings"), (5, 150, "Five viewings"), (10, 250, "Ten viewings")]
# Same bands the code applied before fees became configurable.
DEFAULT_FEE_RULES = [(0, 14_999, 1_500), (15_000, 29_999, 2_500), (30_000, 60_000, 4_000), (60_001, None, 6_000)]


def seed_prices(apps, schema_editor):
    ViewingPackage = apps.get_model("payments", "ViewingPackage")
    ReferralFeeRule = apps.get_model("payments", "ReferralFeeRule")
    ServicePrice = apps.get_model("payments", "ServicePrice")
    if not ViewingPackage.objects.exists():
        for order, (credits, price, name) in enumerate(DEFAULT_PACKAGES):
            ViewingPackage.objects.create(country="KE", name=name, credits=credits, price=price, sort_order=order)
    if not ReferralFeeRule.objects.exists():
        for low, high, amount in DEFAULT_FEE_RULES:
            ReferralFeeRule.objects.create(country="KE", min_rent=low, max_rent=high, fee_type="fixed", amount=amount)
    ServicePrice.objects.get_or_create(country="KE", code="property_verification", defaults={"amount": 2000})


def backfill_payments(apps, schema_editor):
    Payment = apps.get_model("payments", "Payment")
    for payment in Payment.objects.filter(status="successful"):
        receipt = str((payment.provider_payload or {}).get("receipt") or "") or None
        if receipt and Payment.objects.filter(provider_receipt=receipt).exists():
            receipt = None  # duplicate receipt in legacy data: leave for manual review
        Payment.objects.filter(pk=payment.pk).update(provider_receipt=receipt, completed_at=payment.updated_at)


